    ["Search characters"] = "Buscar personajes",
    ["Short facts you write yourself, such as a name or a promise. The character knows them in every talk."] = "Datos breves que tú mismo escribes, como un nombre o una promesa. El personaje los conoce en todas las charlas.",
    ["Short rules this character always follows when talking, for example: Never swear. Answer in one sentence."] = "Reglas breves que este personaje siempre sigue al hablar, por ejemplo: No insultes. Responde en una frase.",
