    ["That character was not found."] = "No se encontró ese personaje.",
    ["The Local AI pack finds these. It is not installed or not ready, so none are collected now."] = "El paquete Local AI encuentra estos datos. No está instalado ni listo, así que por ahora no se recopila nada.",
    ["The bio is too long. Keep it under {max} characters."] = "La biografía es demasiado larga. Mantenla por debajo de {max} caracteres.",
    ["The bio is too short. Use at least {max} characters."] = "La biografía es demasiado corta. Usa al menos {max} caracteres.",
    ["The conversation service is not running, so the editor cannot open. Restart the game."] = "El servicio de conversación no está en marcha, así que el editor no puede abrirse. Reinicia el juego.",
    ["The editor could not be opened. Try again."] = "No se pudo abrir el editor. Inténtalo de nuevo.",
    ["The editor is closed. You can close this tab."] = "El editor está cerrado. Puedes cerrar esta pestaña.",
    ["World rules"] = "Reglas del mundo",
    ["Rules for the whole world, used for every character in every talk: face to face, phone and group chats. Write facts and style, for example how people talk or what nobody knows. They never replace the mod’s own rules."] = "Reglas para todo el mundo, se usan con cada personaje en cada conversación: cara a cara, por teléfono y en chats de grupo. Escribe hechos y estilo, por ejemplo cómo habla la gente o qué no sabe nadie. Nunca reemplazan las reglas propias del mod.",
    ["For example: Nobody in Night City knows V’s name unless V tells them. Everyone speaks casually."] = "Por ejemplo: Nadie en Night City sabe el nombre de V a menos que V se lo diga. Todos hablan de forma informal.",
    ["Applies to every provider: Local AI, Mistral and Custom in the character prompt, and Convai through its dynamic info."] = "Se aplica a todos los proveedores: Local AI, Mistral y Custom en el prompt del personaje, y Convai a través de su información dinámica.",
    ["The world rules are too long. Keep them under {max} characters."] = "Las reglas del mundo son demasiado largas. Mantenlas por debajo de {max} caracteres.",
    ["Revert changes"] = "Revertir cambios",
    ["Clear the world rules?"] = "¿Borrar las reglas del mundo?",
    ["The example lines are too long together. Keep them under {max} characters in all."] = "Las líneas de ejemplo son demasiado largas en conjunto. Mantenlas por debajo de {max} caracteres en total.",
    ["The speaking style is too long. Keep it under {max} characters."] = "El estilo de habla es demasiado largo. Mantenlo por debajo de {max} caracteres.",
    ["Things they always know"] = "Cosas que siempre saben",
    ["Too many example lines. Keep {max} or fewer."] = "Hay demasiadas líneas de ejemplo. Deja {max} o menos.",
    ["Too many memories. Keep {max} or fewer."] = "Hay demasiados recuerdos. Deja {max} o menos.",
    ["Too many rules. Keep {max} or fewer."] = "Hay demasiadas reglas. Deja {max} o menos.",
    ["Who this character is, what they know and how they look. A long bio makes replies slower, so keep it tight."] = "Quién es este personaje, qué sabe y cómo luce. Una biografía larga hace que las respuestas sean más lentas, así que mantenla breve.",
    ["You have changes that are not saved. Leave without saving?"] = "Tienes cambios sin guardar. ¿Salir sin guardar?",
    ["{count} of {max}"] = "{count} de {max}",
    ["Mature content"] = "Contenido para adultos",
    ["Local AI model"] = "Modelo Local AI",
    ["Uncensored model"] = "Modelo sin censura",
    ["No model installed"] = "Sin modelo instalado",
    ["another model"] = "otro modelo",
    ["The Local AI model you chose is missing, does not fit in the free graphics memory or did not start, so {model} was used instead."] = "El modelo Local AI que elegiste falta, no cabe en la memoria gráfica libre o no se inició, así que se usó {model} en su lugar.",
    ["Local AI switched to {model}: the game is using most of your graphics memory."] = "Local AI cambió a {model}: el juego está usando la mayor parte de tu memoria gráfica.",
    ["Choose one of the listed Local AI models."] = "Elige uno de los modelos Local AI de la lista.",
    ["Characters to invite"] = "Personajes para invitar",
    ["Whose memories"] = "Recuerdos de quién",
    ["Invalid Mature content settings."] = "Configuración de contenido para adultos no válida.",
    ["Your message was not sent. Open the text box again and retype it."] = "No se envió tu mensaje. Abre de nuevo el cuadro de texto y vuelve a escribirlo.",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "No utilizable: {models}. Consulta las notas de Local AI, «Añadir tu propio modelo».",
    ["an embedding model, not a chat model"] = "un modelo de embeddings, no de chat",
    ["could not be read"] = "no se pudo leer",
    ["file not found"] = "archivo no encontrado",
    ["not a valid GGUF file"] = "no es un archivo GGUF válido",
    ["{name} (custom)"] = "{name} (personalizado)",
    ["{name}: {reason}"] = "{name}: {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "Preparando {name}: esperando a que el servicio de conversación se conecte…",
    ["Preparing {name}: waiting for the voice model to load…"] = "Preparando {name}: esperando a que se cargue el modelo de voz…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "Preparando {name}: esperando a que se abra la conexión de conversación…",
    ["Preparing {name}: waiting for the game to place the character…"] = "Preparando {name}: esperando a que el juego coloque al personaje…",
    ["Preparing {name}: waiting for the memory service…"] = "Preparando {name}: esperando al servicio de memoria…",
    ["Preparing {count} more companions…"] = "Preparando {count} compañeros más…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "El servicio de conversación no respondió. Espera un momento y vuelve a invitar.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "El modelo de voz no se cargó. Revisa la voz en Ajustes o elige otra, y luego vuelve a invitar.",
    ["The memory service did not respond. Check your connection, then invite again."] = "El servicio de memoria no respondió. Revisa tu conexión y luego vuelve a invitar.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "La conexión de conversación no se abrió. Revisa tu conexión y luego vuelve a invitar.",
    ["Calls are not available during combat."] = "Las llamadas no están disponibles durante el combate.",
    ["Calls are not available right now."] = "Las llamadas no están disponibles en este momento.",
    ["Holocall ended: combat started."] = "Holollamada terminada: ha comenzado el combate.",
    ["Holocall with {name} ended."] = "Holollamada con {name} terminada.",
    ["Live picture unavailable. The call continues with the portrait."] = "Imagen en vivo no disponible. La llamada continúa con el retrato.",
    ["This contact cannot take a holocall."] = "Este contacto no puede recibir una holollamada.",
    ["You are already on a call."] = "Ya estás en una llamada.",
    ["A nearby companion makes one short comment as combat starts and another afterward.\n\nTen-minute cooldown after a fight. Conversations and story scenes come first. Loading a save resets the cooldown."] = "Un compañero cercano comenta brevemente al empezar el combate y otra vez después.\n\nEnfriamiento de diez minutos tras una pelea. Las conversaciones y las escenas de la historia tienen prioridad. Cargar una partida reinicia el enfriamiento.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Pide a un compañero que conduzca hasta el punto del mapa que hayas marcado.\n\nSúbete al asiento del copiloto cuando esté listo.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Auto: sigue el encuentro completado en esta partida.\n\nInformal: habla con esa familiaridad.\n\nNormal: mantiene su trato habitual.\n\nNo implica una relación en curso.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Auto: sigue la relación de esta partida.\n\nRomántico: habla a V como pareja.\n\nNormal: mantiene su trato habitual.\n\nSolo cambia cómo hablan, nunca tus decisiones en el juego.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "El audio Bluetooth llega un poco tarde y los labios y subtítulos pueden adelantarse a la voz. Esto los retrasa para que coincidan, con todas las voces.\n\nAuto: 150 ms mientras Windows reproduce por Bluetooth, ninguno si no. Elige un valor si tus auriculares van más rápido o más lento.\n\nEl diálogo del juego tiene el mismo retraso y no lo corrige.",
    ["Characters sometimes ask about something you said, pick up something from earlier or share a thought that invites an answer.\n\nNow and then, never on every reply, and never while you are leaving, giving an order or fighting."] = "A veces los personajes preguntan por algo que dijiste, retoman algo anterior o comparten una idea que invita a responder.\n\nDe vez en cuando, nunca en cada respuesta, y nunca mientras te vas, das una orden o luchas.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "El historial del Chat se conserva al reiniciar el juego.\n\nOlvidar un personaje borra también sus mensajes y borradores guardados del Chat. Olvidar todos los recuerdos borra todos los chats guardados.",
    ["Cinematic: the game’s regular dialogue subtitles.\n\nAbove the speaker: over the companion who is talking.\n\nThe Subtitles switch turns both off."] = "Cinemático: los subtítulos normales de diálogo del juego.\n\nSobre el hablante: sobre el compañero que habla.\n\nEl interruptor de Subtítulos desactiva ambos.",
    ["Companions comment after you finish collecting loot from the world. Storage transfers stay silent.\n\nOrdinary comments are ten minutes apart; newly acquired Legendary gear has its own two-minute cooldown.\n\nPickups made during a fight are folded into one comment at its end."] = "Los compañeros comentan después de terminar de recoger botín en el mundo. Los traslados al almacén quedan en silencio.\n\nLos comentarios normales están separados diez minutos; el equipo legendario recién obtenido tiene su propio enfriamiento de dos minutos.\n\nLos objetos recogidos durante un combate se agrupan en un solo comentario al final.",
    ["Copy your free key from Mistral first (signing up there needs phone verification). It is read from the clipboard once, checked with Mistral and saved on this computer.\n\nYou can also save it in player-mistral-key.txt in the conversation service folder. Mistral allows about one message a second and about 5,000 turns a day. It sets its own monthly cap, estimated at about 150,000 turns."] = "Copia primero tu clave gratuita de Mistral (registrarse allí requiere verificar el teléfono). Se lee del portapapeles una sola vez, se comprueba con Mistral y se guarda en este ordenador.\n\nTambién puedes guardarla en player-mistral-key.txt, en la carpeta del servicio de conversación. Mistral permite aproximadamente un mensaje por segundo y unos 5000 turnos al día. Mistral fija su propio límite mensual, estimado en unos 150.000 turnos.",
    ["Custom models are ones you added; they join the default choice by size."] = "Los modelos personalizados los has añadido tú; se suman a la elección por tamaño.",
    ["Eyes only: the head stays still and just the eyes move.\n\nSubtle to Strong: the head turns toward you more and more."] = "Solo ojos: la cabeza queda quieta y solo se mueven los ojos.\n\nSutil a Intenso: la cabeza se gira hacia ti cada vez más.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups (joining steps, dismissals, driving instructions, results of companion actions), writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nPreparation progress, joined notices, failures and replies to Stop trip stay visible when it is off."] = "Para pruebas e informes de errores; déjalo desactivado para jugar normalmente.\n\nMuestra avisos habituales (unirse, despedidas, conducción, resultados de acciones de compañeros), escribe un registro de movimiento en la carpeta del mod, registra decisiones de gestos y se añade a los informes de soporte.\n\nEl progreso de preparación, los avisos de unión, los fallos y las respuestas a Detener viaje siguen visibles con esto desactivado.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "Olvidar todos los recuerdos se aplica a estos personajes.\n\nNavegar por el catálogo o invitar a un compañero no suma a nadie a este recuento.",
    ["Gang members, NCPD officers, guards, ripperdocs, shopkeepers, bartenders and passers-by answer as their kind of person.\n\nThey do not know your story and forget you after a save load, except shopkeepers you come back to.\n\nNamed characters are not affected."] = "Miembros de bandas, agentes de la NCPD, guardias, ripperdocs, tenderos, camareros y transeúntes responden como su tipo de persona.\n\nNo conocen tu historia y te olvidan tras cargar una partida, salvo los tenderos a los que vuelves.\n\nLos personajes con nombre no se ven afectados.",
    ["Talk to story characters"] = "Hablar con personajes de la historia",
    ["The game’s own named characters, such as Judy, Jackie, Panam and Rogue, answer when you talk to them where they stand. They use their own voice and memory, and their face follows what they say.\n\nNothing else about them changes: they do not turn, move, gesture or follow. They do not answer during scenes, quest conversations, fights or rides.\n\nTakes effect after you reload your save."] = "Los personajes del propio juego con nombre, como Judy, Jackie, Panam y Rogue, responden cuando les hablas allí donde están. Usan su propia voz y memoria, y su rostro sigue lo que dicen.\n\nNada más en ellos cambia: no se giran, no se mueven, no gesticulan ni te siguen. No responden durante escenas, conversaciones de misiones, peleas ni viajes en vehículo.\n\nSurte efecto después de volver a cargar tu partida.",
    ["{name} is busy right now."] = "{name} no puede hablar en este momento.",
    ["{name} is a story character. Turn on Talk to story characters in Esc > Mods."] = "{name} es un personaje de la historia. Activa esa opción en Esc > mods.",
    ["Talk to ordinary NPCs is off. Turn it on in Esc > Mods."] = "Hablar con PNJ comunes está desactivado. Actívalo en Esc > mods.",
    ["{name} is a child and cannot be talked to."] = "No se puede hablar con {name}: es menor de edad.",
    ["{name} is not a person and cannot be talked to."] = "No se puede hablar con {name}: no es una persona.",
    ["{name} cannot be talked to: the mod cannot tell which voice fits."] = "No se puede hablar con {name}: el mod no sabe qué voz le corresponde.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Si un personaje deja de responder, las voces se detienen o aparece un error: elige Generar informe y envía el archivo que indica al desarrollador, con una breve nota sobre lo que hacías.\n\nLos registros indicados abajo muestran qué salió mal.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "Los personajes invitados se preparan al instante. Sus recuerdos empiezan cuando de verdad hablas con ellos.\n\nLa identidad del jugador se comparte entre todas las partidas y se mantiene tras olvidar.\n\nEl contexto actual del juego describe el mundo que has cargado.",
    ["Only Mature models found. Turn on Mature content to use them."] = "Solo se encontraron modelos para adultos. Activa Contenido para adultos.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Nunca permitido: sexo con menores o sin consentimiento, sexo con personas reales, odio, instrucciones reales de armas o drogas. Una comprobación de seguridad aplica la regla de menores.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Desactivado: respuestas solo en texto, sin voz.\n\nCon los Subtítulos también desactivados, las reacciones automáticas quedan en silencio.",
    ["Pocket: the lightest, runs on your CPU, starts speaking in about 0.2 s.\n\nOmniVoice: richer, especially on harder voices. Needs a capable GPU and the OmniVoice pack (greyed out until it is installed); the higher tiers start in 1 to 2.5 s.\n\nVoxtral: each companion’s own voice from the cloud, with your own Mistral key, in English and many other languages. It loads no local voice model.\n\nConvai: its own cloud voice. A voice that cannot run is replaced by a simpler one, with one notice."] = "Pocket: el más ligero, usa tu CPU y empieza a hablar en unos 0,2 s.\n\nOmniVoice: más rico, sobre todo en voces difíciles. Necesita una GPU capaz y el paquete de OmniVoice (atenuado hasta que se instale); los niveles altos empiezan en 1 a 2,5 s.\n\nVoxtral: la voz propia de cada compañero desde la nube, con tu propia clave de Mistral, en inglés y en muchos otros idiomas. No carga ningún modelo de voz local.\n\nConvai: su propia voz en la nube. Una voz que no pueda ejecutarse se sustituye por una más sencilla, con un solo aviso.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Consulta lo que recuerda cada personaje y haz que uno o todos olviden.\n\nLos recuerdos se conservan entre partidas.",
    ["Shows companion replies as text.\n\nWith Voice playback off as well, automatic reactions stay silent."] = "Muestra las respuestas como texto.\n\nCon la Reproducción de voz apagada, las reacciones automáticas quedan en silencio.",
    ["Voxtral · not with Mature"] = "Voxtral · no con adultos",
    ["Voxtral is not used with Mature content."] = "Voxtral no se usa con el Contenido para adultos.",
    ["Needs Local AI or Custom."] = "Necesita Local AI o Custom.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+). Needs Local AI or Custom."] = "Lenguaje fuerte, violencia gráfica, drogas y, entre adultos que consienten, coqueteo y sexo. Solo adultos (18+). Necesita Local AI o Custom.",
    ["From Convai or Mistral, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "Desde Convai o Mistral, activarlo elige Local AI, o Personalizado si Local AI no está instalada. Con Local AI también elige el modelo sin censura más grande que quepa. Desactivarlo restaura tus elecciones.",
    ["Choosing Convai or Mistral turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "Elegir Convai o Mistral lo desactiva. Voxtral no se usa con ello: una voz de Voxtral pasa a Pocket y vuelve cuando se desactiva.",
    ["Use it if companions seem to look above or below your eyes."] = "Úsalo si los compañeros parecen mirar por encima o por debajo de tus ojos.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Nube de Mistral",
    ["Voxtral · needs Mistral key"] = "Voxtral · necesita clave Mistral",
    ["{name} (custom · too large)"] = "{name} (personalizado · muy grande)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (personalizado, {size} GB, necesita {need} GB)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (personalizado, {size} GB, demasiado grande para esta tarjeta)",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Borra los recuerdos sobre ti de todos los personajes con los que has hablado.\n\nTu identidad de jugador se conserva. Antes se pide confirmación.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Guarda un archivo de informe para enviar al desarrollador.\n\nLas claves de API, tokens, ID, audio del micrófono y texto de conversación no se incluyen. Sin el servicio de conversación, se crea un informe más corto con los archivos que el juego puede leer.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: installed."] = "Modelos sin censura del Mature pack (para Local AI): efecto completo. Los estándar casi siempre rechazan el sexo. Pack: instalado.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s Hugging Face page)."] = "Modelos sin censura del Mature pack (para Local AI): efecto completo. Los estándar casi siempre rechazan el sexo. Pack: no instalado (opcional, en la página de Hugging Face del mod).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Sin elegir uno, Local AI carga el modelo más grande que quepa en tu memoria gráfica libre.\n\nUn modelo a la vez; los cambios se aplican en la siguiente carga. Si falta un modelo, es demasiado grande o falla, se sustituye por el mayor que quepa, con un aviso.",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "Convai no aceptó tu clave de API. Revísala en Ajustes > Proveedor de conversación.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "Local AI no pudo iniciarse. Revisa Local AI en Ajustes > Proveedor de conversación.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "Mistral no aceptó tu clave. Revísala en Ajustes > Proveedor de conversación.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Mistral aún no tiene clave, así que se usa Convai. Añade tu clave en Ajustes > Proveedor de conversación.",
    ["Requires a Mistral key (add it in Settings > Conversation provider)"] = "Requiere una clave de API de Mistral (añádela en Ajustes > Proveedor de conversación)",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "Hablar con los compañeros necesita Convai por ahora. Ajusta Proveedor de conversación a Convai (plan gratuito) en Ajustes > Proveedor de conversación, o escribe tu mensaje.",
    ["The conversation limit has been reached. Try again later, or add a free Mistral key and set Conversation provider to Mistral in Settings > Conversation provider."] = "Se ha alcanzado el límite de conversaciones. Inténtalo más tarde o añade una clave de API gratuita de Mistral y pon el Proveedor de conversación en Mistral en Ajustes > Proveedor de conversación.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "Tu clave de API de Convai ha alcanzado el límite de su plan. Inténtalo más tarde o añade otra clave en Ajustes > Proveedor de conversación.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Mistral (free, with your own free key) allows about 5,000 turns a day. Local AI is unlimited and runs on your PC."] = "Has alcanzado el límite diario de Convai (plan gratuito). Se restablece mañana. Para seguir hablando ahora, elige otro proveedor en Ajustes > Proveedor de conversación. Mistral (gratis, con tu propia clave gratuita) permite unos 5000 turnos al día. Local AI es ilimitada y funciona en tu PC.",
    ["Today’s {limit} Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Convai: {limit} turnos agotados hoy.\nPrueba Mistral (clave gratis, ~5000/día) o Local AI (sin límite).",
    ["Today’s Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Convai: turnos agotados hoy.\nPrueba Mistral (clave gratis, ~5000/día) o Local AI (sin límite).",
    ["Convai is answering right now, so these changes have no effect yet. Choose Mistral, Local AI or Custom as the conversation provider in the settings."] = "Convai está respondiendo ahora, así que estos cambios aún no tienen efecto. Elige Mistral, Local AI o Personalizado como proveedor de conversación en los ajustes.",
    ["Your changes work with Mistral, Local AI and Custom. They do not apply to Convai."] = "Tus cambios funcionan con Mistral, Local AI y Personalizado. No se aplican a Convai.",
    ["Paste"] = "Pegar",
    ["no Omni pack"] = "sin paquete Omni",
    ["Add your Convai API key below to see and buy a plan."] = "Añade tu clave de API de Convai abajo para ver los planes y comprar uno.",
    ["Add your Convai API key first."] = "Añade primero tu clave de API de Convai.",
    ["Add your Convai API key first: copy it, then choose Paste on the Convai API key row."] = "Añade primero tu clave de API de Convai: cópiala y luego elige Pegar en la fila Clave de API de Convai.",
    ["Asking Convai for the payment page…"] = "Pidiendo a Convai la página de pago…",
    ["Asks Convai which plan your key has now. After paying, it can take about 15 seconds."] = "Pregunta a Convai qué plan tiene ahora tu clave. Después de pagar, puede tardar unos 15 segundos.",
    ["Billed every month."] = "Se cobra cada mes.",
    ["Billed once a year."] = "Se cobra una vez al año.",
    ["Buy"] = "Comprar",
    ["Check"] = "Revisar",
    ["Check my plan"] = "Revisar mi plan",
    ["Checking your plan…"] = "Revisando tu plan…",
    ["Choose Check my plan to ask Convai."] = "Elige Revisar mi plan para preguntar a Convai.",
    ["Contacting Convai…"] = "Contactando con Convai…",
    ["Convai could not start the payment. Try again later."] = "Convai no pudo iniciar el pago. Inténtalo más tarde.",
    ["Convai did not accept your API key."] = "Convai no aceptó tu clave de API.",
    ["Convai does not show a paid plan for your key yet."] = "Convai todavía no muestra un plan de pago para tu clave.",
    ["Convai has not confirmed your plan yet. Check it in Settings > Convai paid tier."] = "Convai aún no ha confirmado tu plan. Revísalo en Ajustes > Plan de pago de Convai.",
    ["Convai paid tier"] = "Plan de pago de Convai",
    ["Convai’s payment page is open in your browser. Your plan is active about 15 seconds after you pay."] = "La página de pago de Convai está abierta en tu navegador. Tu plan se activa unos 15 segundos después de pagar.",
    ["Convai’s payment service did not answer. Try again in a moment."] = "El servicio de pagos de Convai no respondió. Inténtalo de nuevo en un momento.",
    ["Convai’s plans for this mod: more Convai conversations on your own Convai API key. Opens a page with the plans and their prices."] = "Planes de Convai para este mod: más conversaciones de Convai con tu propia clave de API de Convai. Abre una página con los planes y sus precios.",
    ["Conversations with Convai API key chosen as the provider use this plan."] = "Las conversaciones con la clave de API de Convai elegida como proveedor usan este plan.",
    ["Get your Convai API key"] = "Obtén tu clave de API de Convai",
    ["Manage or cancel plan"] = "Gestionar o cancelar plan",
    ["Free"] = "Gratis",
    ["Gamer, monthly"] = "Gamer, mensual",
    ["Gamer, yearly"] = "Gamer, anual",
    ["Gamer Pro, monthly"] = "Gamer Pro, mensual",
    ["Gamer Pro, yearly"] = "Gamer Pro, anual",
    ["Current plan"] = "Plan actual",
    ["This is your current plan. To change or cancel it, choose Manage or cancel plan below."] = "Este es tu plan actual. Para cambiarlo o cancelarlo, elige Gestionar o cancelar plan más abajo.",
    ["No key added"] = "No se ha añadido ninguna clave",
    ["Not checked yet"] = "Aún no revisado",
    ["Opened in your browser."] = "Abierto en tu navegador.",
    ["Opening the page in your browser…"] = "Abriendo la página en tu navegador…",
    ["Opens Convai’s payment page (Stripe) in your browser. You pay Convai directly; the mod never sees your card. Your plan is active about 15 seconds after you pay, and conversations then use your Convai API key."] = "Abre la página de pago de Convai (Stripe) en tu navegador. Pagas directamente a Convai; el mod nunca ve tu tarjeta. Tu plan se activa unos 15 segundos después de pagar, y las conversaciones usan entonces tu clave de API de Convai.",
    ["Opens convai.com in your browser. Sign in or make a free account, copy your API key, then come back and choose Paste below."] = "Abre convai.com en tu navegador. Inicia sesión o crea una cuenta gratuita, copia tu clave de API y luego vuelve y elige Pegar más abajo.",
    ["Opens your Convai billing page in your browser. Sign in with the same Convai account to change or cancel your plan."] = "Abre tu página de facturación de Convai en tu navegador. Inicia sesión con la misma cuenta de Convai para cambiar o cancelar tu plan.",
    ["Plans"] = "Planes",
    ["Plans Convai made for this mod. They give your own Convai API key more conversations; the free tier stays as it is."] = "Planes que Convai creó para este mod. Dan más conversaciones a tu propia clave de API de Convai; el plan gratuito se mantiene igual.",
    ["Prices in US dollars. You can cancel at any time on Convai’s billing page."] = "Precios en dólares estadounidenses. Puedes cancelar en cualquier momento en la página de facturación de Convai.",
    ["The conversation service is not running, so plans cannot be shown. Restart the game."] = "El servicio de conversación no está en marcha, así que no se pueden mostrar los planes. Reinicia el juego.",
    ["This key has no paid plan. Choose a plan below."] = "Esta clave no tiene plan de pago. Elige un plan más abajo.",
    ["Your Convai plan"] = "Tu plan de Convai",
    ["Your Convai plan is active."] = "Tu plan de Convai está activo.",
    ["Your Convai plan is active. Choose Convai API key in Settings > Conversation provider."] = "Tu plan de Convai está activo. Elige Clave de API de Convai en Ajustes > Proveedor de conversación.",
    ["Your Convai plan is active. Conversations now use your Convai API key."] = "Tu plan de Convai está activo. Las conversaciones ahora usan tu clave de API de Convai.",
    ["Your browser could not be opened."] = "No se pudo abrir tu navegador.",
    ["Your plan could not be read right now. Try again in a moment."] = "No se pudo leer tu plan en este momento. Inténtalo de nuevo en un momento.",
    ["{count} Convai interactions a month."] = "{count} interacciones de Convai al mes.",
    ["{plan}, {price} a month"] = "{plan}, {price} al mes",
    ["{plan}, {price} a year"] = "{plan}, {price} al año",
    ["Sign in with Convai"] = "Iniciar sesión con Convai",
    ["Sign in"] = "Iniciar sesión",
    ["Opens Convai’s sign-in page in your browser.\n\nSign in or make a free account, and your Convai API key is saved on this computer, the same as Paste. You have five minutes."] = "Abre la página de inicio de sesión de Convai en tu navegador.\n\nInicia sesión o crea una cuenta gratuita, y tu clave de API de Convai se guardará en este equipo, igual que con Pegar. Tienes cinco minutos.",
    ["Opening Convai’s sign-in page in your browser…"] = "Abriendo la página de inicio de sesión de Convai en tu navegador…",
    ["Sign in on the Convai page in your browser. Your key is saved here when you finish."] = "Inicia sesión en la página de Convai en tu navegador. Tu clave se guardará aquí cuando termines.",
    ["Signed in. Your Convai API key is saved."] = "Sesión iniciada. Tu clave de API de Convai se ha guardado.",
    ["The sign-in took too long. Choose Sign in with Convai to try again."] = "El inicio de sesión tardó demasiado. Elige Iniciar sesión con Convai para intentarlo de nuevo.",
    ["The sign-in did not finish. Try again, or copy your key from convai.com and choose Paste."] = "El inicio de sesión no se completó. Vuelve a intentarlo o copia tu clave desde convai.com y elige Pegar.",
    ["Choose one of the listed voices for V."] = "Elige una de las voces de la lista para V.",
    ["Pocket · On your PC"] = "Pocket · En tu PC",
    ["Johnny in your head"] = "Johnny en tu cabeza",
    ["Choose how often Johnny speaks up."] = "Elige con qué frecuencia interviene Johnny.",
    ["A display name is too long. Keep each one under {max} characters."] = "Un nombre para mostrar es demasiado largo. Mantén cada uno por debajo de {max} caracteres.",
    ["A clip you add replaces the shipped voice of this character for Pocket, OmniVoice and the Voxtral cloud voice."] = "Un clip que añadas sustituye la voz original de este personaje para Pocket, OmniVoice y la voz en la nube de Voxtral.",
    ["A new or removed clip counts from the next line this character speaks, once the current reply is over. Nothing needs restarting."] = "Un clip nuevo o eliminado cuenta desde la siguiente frase de este personaje, cuando termine la respuesta actual. No hace falta reiniciar nada.",
    ["A record name can only use letters, digits, dots, dashes and underscores, for example Character.Rebecca."] = "Un nombre de registro solo puede usar letras, dígitos, puntos, guiones y guiones bajos, por ejemplo Character.Rebecca.",
    ["Add a display name"] = "Añadir un nombre para mostrar",
    ["Add a record name"] = "Añadir un nombre de registro",
    ["Add a record name or a display name, so the game can find this character."] = "Añade un nombre de registro o un nombre para mostrar, para que el juego pueda encontrar a este personaje.",
    ["Add voice clip"] = "Añadir clip de voz",
    ["Another character of yours, {other}, already answers to this record or name."] = "Otro de tus personajes, {other}, ya responde a este registro o nombre.",
    ["Choose a gender"] = "Elige un género",
    ["Choose a gender."] = "Elige un género.",
    ["Chosen file: {name} ({size}). It is checked when you save it."] = "Archivo elegido: {name} ({size}). Se comprueba cuando lo guardes.",
    ["Chosen file: {name}, {seconds} seconds."] = "Archivo elegido: {name}, {seconds} segundos.",
    ["Clip removed."] = "Clip eliminado.",
    ["Delete character"] = "Eliminar personaje",
    ["Delete {name}? The character, its voice clip and what it remembers of you are removed."] = "¿Eliminar {name}? Se borrarán el personaje, su clip de voz y lo que recuerda de ti.",
    ["Display names"] = "Nombres para mostrar",
    ["Edit a character’s bio, speaking style, speaking rules and memories, or make a character of your own, in your browser.\n\nWorks with Mistral, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Edita en tu navegador la biografía, el estilo de habla, las reglas de habla y los recuerdos de un personaje, o crea uno propio.\n\nFunciona con Mistral, Local AI y Personalizado, no con Convai. Los cambios se aplican desde la siguiente respuesta.",
    ["Female"] = "Femenino",
    ["Filled in from the character you were facing: {name}."] = "Rellenado con el personaje al que mirabas: {name}.",
    ["For example: Character.Rebecca"] = "Por ejemplo: Character.Rebecca",
    ["For example: Rebecca"] = "Por ejemplo: Rebecca",
    ["Gender"] = "Género",
    ["Give the character a name."] = "Ponle un nombre al personaje.",
    ["How the game finds this character"] = "Cómo encuentra el juego a este personaje",
    ["It picks the voice when the character has no clip."] = "Cuando el personaje no tiene clip, el género elige la voz.",
    ["Male"] = "Masculino",
    ["Memories"] = "Recuerdos",
    ["Name"] = "Nombre",
    ["New character"] = "Nuevo personaje",
    ["No clip yet."] = "Todavía no hay clip.",
    ["Optional. Pocket, OmniVoice and the Voxtral cloud voice copy a clip you add. Without one the character speaks with a generic voice that fits the gender."] = "Opcional. Pocket, OmniVoice y la voz en la nube de Voxtral copian un clip que añadas. Sin clip, el personaje habla con una voz genérica que encaja con su género.",
    ["Play saved clip"] = "Reproducir clip guardado",
    ["Record names"] = "Nombres de registro",
    ["Remove clip"] = "Quitar clip",
    ["Remove the voice clip? The character goes back to a generic voice."] = "¿Quitar el clip de voz? El personaje vuelve a una voz genérica.",
    ["Remove the voice clip? {name} goes back to the shipped voice."] = "¿Quitar el clip de voz? {name} vuelve a la voz original.",
    ["Save clip"] = "Guardar clip",
    ["Save the character first. Then it can have a voice clip, and it starts to remember your talks."] = "Guarda primero el personaje. Después podrá tener un clip de voz y empezará a recordar tus charlas.",
    ["Saved clip: {seconds} seconds."] = "Clip guardado: {seconds} segundos.",
    ["Saved. The clip is a little long: 10 to 18 seconds copies best."] = "Guardado. El clip es un poco largo: de 10 a 18 segundos es lo que mejor se copia.",
    ["Saved. The clip is a little short: 10 to 18 seconds copies best."] = "Guardado. El clip es un poco corto: de 10 a 18 segundos es lo que mejor se copia.",
    ["That file is not a recording the voices can read. Use a WAV, MP3, OGG or FLAC file."] = "Ese archivo no es una grabación que las voces puedan leer. Usa un archivo WAV, MP3, OGG o FLAC.",
    ["That file is too big for a voice clip."] = "Ese archivo es demasiado grande para un clip de voz.",
    ["The clip is mostly silence. Use a clip where somebody is talking most of the time."] = "El clip es casi todo silencio. Usa un clip en el que alguien hable la mayor parte del tiempo.",
    ["The clip is too long. Use at most {max} seconds."] = "El clip es demasiado largo. Usa como máximo {max} segundos.",
    ["The clip is too short. Use at least {min} seconds."] = "El clip es demasiado corto. Usa al menos {min} segundos.",
    ["The game did not name anyone. Face the character, then choose Settings > Edit characters > Open in the game again."] = "El juego no ha nombrado a nadie. Mira al personaje y luego elige de nuevo Ajustes > Editar personajes > Abrir en el juego.",
    ["The game recognises the person you talk to by a record name, a display name, or both. A record name looks like Character.Rebecca or NCA.Rebecca. Add at least one."] = "El juego reconoce a la persona con la que hablas por un nombre de registro, un nombre para mostrar, o ambos. Un nombre de registro tiene este aspecto: Character.Rebecca o NCA.Rebecca. Añade al menos uno.",
    ["The name is too long. Keep it under {max} characters."] = "El nombre es demasiado largo. Mantenlo por debajo de {max} caracteres.",
    ["The name of the character’s record in the game files."] = "El nombre del registro del personaje en los archivos del juego.",
    ["The name the character goes by. They give it when somebody asks who they are."] = "El nombre con el que se le conoce. Lo da cuando alguien le pregunta quién es.",
    ["The name the game shows for the character."] = "El nombre que muestra el juego para el personaje.",
    ["The recording is distorted. Record it again, a little quieter."] = "La grabación está distorsionada. Grábala de nuevo, un poco más bajo.",
    ["The recording is too low in quality. Use at least {min} Hz."] = "La calidad de la grabación es demasiado baja. Usa al menos {min} Hz.",
    ["The recording is too quiet to copy. Record it louder, or closer to the microphone."] = "La grabación es demasiado baja para copiarla. Grábala más alto o más cerca del micrófono.",
    ["The saved clip could not be loaded."] = "No se pudo cargar el clip guardado.",
    ["The words said in the clip are too long. Keep them under {max} characters."] = "Las palabras dichas en el clip son demasiado largas. Mantenlas por debajo de {max} caracteres.",
    ["This character speaks with a generic voice that fits the gender."] = "Este personaje habla con una voz genérica que encaja con su género.",
    ["This character speaks with the shipped voice."] = "Este personaje habla con la voz original.",
    ["This computer cannot convert that file. Save it as a WAV and try again."] = "Este ordenador no puede convertir ese archivo. Guárdalo como WAV e inténtalo de nuevo.",
    ["Too many display names. Keep {max} or fewer."] = "Demasiados nombres para mostrar. Deja {max} o menos.",
    ["Too many record names. Keep {max} or fewer."] = "Demasiados nombres de registro. Deja {max} o menos.",
    ["Type the words said in the clip, at least {min} characters."] = "Escribe las palabras dichas en el clip, de al menos {min} caracteres.",
    ["Type what the clip says, as spoken. OmniVoice needs it to copy the voice."] = "Escribe lo que dice el clip, tal como se pronuncia. OmniVoice lo necesita para copiar la voz.",
    ["Use the character I’m facing"] = "Usar el personaje al que miro",
    ["Use {min} to {max} seconds of one person speaking clearly, with no music or other voices. {goodMin} to {goodMax} seconds copies best. WAV, MP3, OGG or FLAC."] = "Usa de {min} a {max} segundos de una sola persona que hable con claridad, sin música ni otras voces. De {goodMin} a {goodMax} segundos es lo que mejor se copia. WAV, MP3, OGG o FLAC.",
    ["Voice"] = "Voz",
    ["You have as many voice clips as the editor keeps ({max}). Remove one first."] = "Ya tienes tantos clips de voz como guarda el editor ({max}). Quita uno primero.",
    ["Who this character is, what they know and how they look. Writing it as “I am …” works best. A long bio makes replies slower, so keep it tight."] = "Quién es este personaje, qué sabe y cómo es. Escribirlo como «Soy …» funciona mejor. Una biografía larga hace las respuestas más lentas, así que mantenla concisa.",
    ["Words said in the clip"] = "Palabras dichas en el clip",
    ["You have made as many characters as the editor keeps ({max}). Delete one first."] = "Ya has creado tantos personajes como permite el editor ({max}). Elimina uno primero.",
    ["Your character"] = "Tu personaje",
    ["Your characters"] = "Tus personajes",
    ["Your own characters talk only with Mistral, Local AI or Custom. With Convai they speak as an ordinary person."] = "Tus propios personajes solo hablan con Mistral, IA local o Personalizado. Con Convai hablan como una persona normal.",
    ["{name} is one of your own characters. They need Mistral, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} es uno de tus propios personajes. Necesita Mistral, IA local o Personalizado, así que con Convai habla como una persona normal.",
    ["{other} already has a profile in the mod, and that profile always wins. Use another record or name."] = "{other} ya tiene un perfil en el mod, y ese perfil siempre prevalece. Usa otro registro o nombre.",
    ["A pack is one folder too deep. See Help in Settings."] = "Un paquete tiene una carpeta de más. Ver Ayuda en Ajustes.",
    ["All files found."] = "Todos los archivos encontrados.",
    ["Browser"] = "Navegador",
    ["Found."] = "Encontrado.",
    ["Found: {list}."] = "Encontrado: {list}.",
    ["Game version"] = "Versión del juego",
    ["Graphics card"] = "Tarjeta gráfica",
    ["Internet"] = "Internet",
    ["Loaded."] = "Cargado.",
    ["Local AI could not start. Generate a report below and send it, or choose another conversation provider."] = "La IA local no pudo iniciarse. Genera un informe abajo y envíalo, o elige otro proveedor de conversación.",
    ["Local AI found no graphics card it can use. It needs an NVIDIA or AMD card with a current driver. Update the driver, or choose another conversation provider."] = "La IA local no encontró ninguna tarjeta gráfica compatible. Necesita una tarjeta NVIDIA o AMD con un controlador actualizado. Actualiza el controlador o elige otro proveedor de conversación.",
    ["Missing: {files}. Extract the Scripts zip into the Cyberpunk 2077 folder again and let it replace the files."] = "Faltan: {files}. Extrae de nuevo el zip Scripts en la carpeta de Cyberpunk 2077 y deja que reemplace los archivos.",
    ["Mod Organizer 2. Files the mod creates go to its Overwrite folder; leave them there. Mention Mod Organizer 2 when you send a report."] = "Mod Organizer 2. Los archivos que crea el mod van a su carpeta Overwrite; déjalos ahí. Menciona Mod Organizer 2 al enviar un informe.",
    ["Mod files"] = "Archivos del mod",
    ["Mod manager"] = "Gestor de mods",
    ["Moved into place from {folder}: {packs}."] = "Colocados desde {folder}: {packs}.",
    ["No Local AI pack found. Download one from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, or choose another conversation provider."] = "No se encontró ningún paquete de IA local. Descárgalo desde la página de Hugging Face del mod y extráelo en la carpeta de Cyberpunk 2077, o elige otro proveedor de conversación.",
    ["No problem found. Select a line to see what was checked."] = "No se encontró ningún problema. Selecciona una línea para ver qué se comprobó.",
    ["No sign of the conversation service in this session: the Runtime is missing or did not load. Extract the Runtime zip straight into the Cyberpunk 2077 folder (not into a new folder), check that red4ext/plugins/AiNpcCyberpunkMod is there, then restart the game. The Runtime is a separate download from the mod’s Hugging Face page; the Nexus page links to it."] = "No hay señales del servicio de conversación en esta sesión: falta el Runtime o no se cargó. Extrae el zip del Runtime directamente en la carpeta de Cyberpunk 2077 (no en una carpeta nueva), comprueba que existe red4ext/plugins/AiNpcCyberpunkMod y luego reinicia el juego. El Runtime es una descarga aparte desde la página de Hugging Face del mod; la página de Nexus enlaza a ella.",
    ["None found: installed by hand."] = "No encontrado: instalado a mano.",
    ["None installed. They are optional."] = "Ninguno instalado. Son opcionales.",
    ["Not needed: Local AI and the voice run on this PC."] = "No necesario: la IA local y la voz se ejecutan en este PC.",
    ["Not used"] = "No se usa",
    ["Not your conversation provider. Choose it in Settings > Conversation provider."] = "No es tu proveedor de conversación. Elígelo en Ajustes > Proveedor de conversación.",
    ["Note"] = "Nota",
    ["OK"] = "OK",
    ["Optional packs"] = "Paquetes opcionales",
    ["Problem"] = "Problema",
    ["Problems found: {count}. Select a line marked Problem to read what to do."] = "Problemas encontrados: {count}. Selecciona una línea marcada como Problema para leer qué hacer.",
    ["RED4ext is not loaded. Install it from Nexus Mods, then restart the game. It also starts the conversation service."] = "RED4ext no está cargado. Instálalo desde Nexus Mods y reinicia el juego. También inicia el servicio de conversación.",
    ["Reached {host}."] = "Conectado a {host}.",
    ["Scripts and Runtime"] = "Scripts y Runtime",
    ["Scripts {scripts} and Runtime {runtime}."] = "Scripts {scripts} y Runtime {runtime}.",
    ["Setup check"] = "Comprobación de instalación",
    ["Some mod files are missing. Extract the Scripts zip again. See Help in Settings."] = "Faltan archivos del mod. Extrae de nuevo el zip Scripts. Ver Ayuda en Ajustes.",
    ["Some pack files could not be moved into place because different files are already there. Extract the pack into the Cyberpunk 2077 folder again and let it replace the files."] = "No se pudieron colocar algunos archivos del paquete porque ya hay otros distintos. Extrae el paquete de nuevo en la carpeta de Cyberpunk 2077 y deja que reemplace los archivos.",
    ["The Runtime is incomplete ({code}). Download it again and extract it into the Cyberpunk 2077 folder (or apply the Runtime update zips in order), then restart the game."] = "El Runtime está incompleto ({code}). Descárgalo de nuevo, extráelo en la carpeta de Cyberpunk 2077 (o aplica los zips de actualización del Runtime en orden) y reinicia el juego.",
    ["The settings file of the launcher, launcher.ini, is missing from red4ext/plugins/AiNpcCyberpunkMod, so the game cannot start the conversation service. Extract the Runtime zip straight into the Cyberpunk 2077 folder again (by hand, also with Vortex) and let it replace the files, then restart the game."] = "Falta el archivo de ajustes del lanzador, launcher.ini, en red4ext/plugins/AiNpcCyberpunkMod, así que el juego no puede iniciar el servicio de conversación. Extrae de nuevo el zip del Runtime directamente en la carpeta de Cyberpunk 2077 (a mano, también con Vortex) y deja que reemplace los archivos; luego reinicia el juego.",
    ["The conversation service cannot reach the internet. See Help in Settings."] = "El servicio de conversación no tiene acceso a Internet. Ver Ayuda en Ajustes.",
    ["The conversation service cannot reach {host}. Allow Node.js through your firewall or antivirus (Windows asks once; choose Allow), check your internet, then restart the game."] = "El servicio de conversación no puede conectarse a {host}. Permite Node.js en tu firewall o antivirus (Windows pregunta una sola vez; elige Permitir acceso), revisa tu conexión a Internet y reinicia el juego.",
    ["The conversation service could not start ({code}). Restart the game. If it happens again, generate a report below and send it."] = "El servicio de conversación no pudo iniciarse ({code}). Reinicia el juego. Si vuelve a pasar, genera un informe abajo y envíalo.",
    ["The conversation service did not start. Is the Runtime installed? See Help in Settings."] = "El servicio de conversación no arrancó. ¿Está instalado el Runtime? Ver Ayuda en Ajustes.",
    ["The game version could not be read."] = "No se pudo leer la versión del juego.",
    ["This PC cannot look up {host}. Check your internet connection, then restart the game."] = "Este PC no puede resolver {host}. Revisa tu conexión a Internet y reinicia el juego.",
    ["Open r6/logs/redscript_rCURRENT.log. A mod it names is why the scripts did not load."] = "Abre r6/logs/redscript_rCURRENT.log. Un mod citado ahí impide cargar los scripts.",
    ["This mod’s scripts did not load. Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Missing or old Codeware, Audioware or redscript, or a game version other than 2.31, can also cause it."] = "Los scripts de este mod no se cargaron. Abre r6/logs/redscript_rCURRENT.log. Si el error nombra otro mod, ese mod es el problema. También pueden causarlo un Codeware, Audioware o redscript ausente o antiguo, o una versión del juego distinta de 2.31.",
    ["Missing: {names}. Install them and restart the game."] = "Faltan: {names}. Instálalos y reinicia el juego.",
    ["Install or update: {names}. Then restart the game."] = "Instala o actualiza: {names}. Luego reinicia el juego.",
    ["Codeware is too old. Update it from Nexus Mods, then restart the game."] = "Codeware es demasiado antiguo. Actualízalo desde Nexus Mods y reinicia el juego.",
    ["Audioware {version} is installed, but this mod’s scripts were built without it. Update Audioware to 1.9.9 or newer from Nexus Mods, then restart the game. If it is already up to date, generate a report below and send it."] = "Audioware {version} está instalado, pero los scripts de este mod se compilaron sin él. Actualiza Audioware a 1.9.9 o posterior desde Nexus Mods y reinicia el juego. Si ya está actualizado, genera un informe abajo y envíalo.",
    ["Audioware is missing. Install Audioware 1.9.9 or newer from Nexus Mods (nexusmods.com/cyberpunk2077/mods/12001), extract it into the Cyberpunk 2077 folder, then restart the game."] = "Falta Audioware. Instala Audioware 1.9.9 o posterior desde Nexus Mods (nexusmods.com/cyberpunk2077/mods/12001), extráelo en la carpeta de Cyberpunk 2077 y reinicia el juego.",
    ["Audioware is installed but unused. Update it to 1.9.9 or newer, then restart the game."] = "Audioware está instalado pero no se usa. Actualízalo a 1.9.9 o posterior y reinicia el juego.",
    ["Version {version}."] = "Versión {version}.",
    ["Version {version}. The mod is tested on 2.31 only, so some things may not work."] = "Versión {version}. El mod solo se ha probado en la 2.31, así que algunas cosas podrían no funcionar.",
    ["Vortex. Install the Runtime and the optional packs by hand into the Cyberpunk 2077 folder, as the install steps say."] = "Vortex. Instala a mano el Runtime y los paquetes opcionales en la carpeta de Cyberpunk 2077, como indican los pasos de instalación.",
    ["{name} is missing. Install it from Nexus Mods, then restart the game."] = "Falta {name}. Instálalo desde Nexus Mods y reinicia el juego.",
    ["{name}, {memory} GB of video memory."] = "{name}, {memory} GB de memoria de vídeo.",
    ["{packs} is one folder too deep, in {folder}. Restart the game and the mod moves it into place. If it is still there afterwards, move the red4ext folder inside it into the Cyberpunk 2077 folder."] = "{packs} tiene una carpeta de más, dentro de {folder}. Reinicia el juego y el mod lo moverá a su sitio. Si sigue ahí después, mueve la carpeta red4ext que hay dentro a la carpeta de Cyberpunk 2077.",
    ["Add an endpoint URL and a model ID first."] = "Añade antes la URL del endpoint y el ID de modelo.",
    ["Convai: the custom provider is not set up yet"] = "Convai: proveedor personalizado aún sin configurar",
    ["Copy the base URL from your provider, for example https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 or http://localhost:11434/v1 (Ollama). It is read from the clipboard once and saved on this computer.\n\nOnly this computer and your home network may use http://. You can also fill in endpoint=, model= and api-key= in player-custom-endpoint.txt in the conversation service folder.\n\nNothing is sent until you choose this provider or press Test connection."] = "Copia la URL base de tu proveedor, por ejemplo https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 o http://localhost:11434/v1 (Ollama). Se lee del portapapeles una sola vez y se guarda en este ordenador.\n\nSolo este ordenador y tu red doméstica pueden usar http://. También puedes rellenar endpoint=, model= y api-key= en player-custom-endpoint.txt, en la carpeta del servicio de conversación.\n\nNo se envía nada hasta que elijas este proveedor o pulses Probar conexión.",
    ["Copy the model ID from your provider first, for example meta-llama/llama-3.1-8b-instruct on OpenRouter or llama3.2 on Ollama. It is read from the clipboard once and saved on this computer."] = "Copia primero el ID del modelo de tu proveedor, por ejemplo meta-llama/llama-3.1-8b-instruct en OpenRouter o llama3.2 en Ollama. Se lee del portapapeles una sola vez y se guarda en este ordenador.",
    ["Copy your API key from your provider first. It is read from the clipboard once and saved on this computer only. A server on your own computer, such as Ollama or LM Studio, usually needs no key."] = "Copia primero tu clave de API de tu proveedor. Se lee del portapapeles una sola vez y se guarda solo en este ordenador. Un servidor en tu propio ordenador, como Ollama o LM Studio, normalmente no necesita clave.",
    ["Custom (OpenAI-compatible)"] = "Personalizado (API OpenAI)",
    ["Custom API key"] = "Clave API propia",
    ["Custom endpoint URL"] = "URL de endpoint propia",
    ["Custom model ID"] = "ID de modelo propio",
    ["Custom provider replies are spoken by a local voice instead of the Convai cloud voice."] = "Las respuestas del proveedor personalizado usan voz local, no la voz en la nube de Convai.",
    ["Custom: key not accepted"] = "Personalizado: clave rechazada",
    ["Custom: model unavailable"] = "Personalizado: modelo no disponible",
    ["Custom: out of credits"] = "Personalizado: sin créditos",
    ["Custom: rate limited for now"] = "Personalizado: límite temporal",
    ["Deletes the saved endpoint URL. The custom provider needs one to answer."] = "Borra la URL del endpoint guardada. El proveedor personalizado la necesita para responder.",
    ["Deletes the saved key. Replies from the custom provider are then asked for without a key."] = "Borra la clave guardada. Después, las respuestas del proveedor personalizado se piden sin clave.",
    ["Deletes the saved model ID. The custom provider needs one to answer."] = "Borra el ID de modelo guardado; el proveedor personalizado lo necesita.",
    ["Failed"] = "Error",
    ["It answered in {ms} ms."] = "Respondió en {ms} ms.",
    ["It could not be saved."] = "No se pudo guardar.",
    ["Model ID: {model}"] = "ID de modelo: {model}",
    ["Only https:// works outside this computer and your home network."] = "Solo https:// funciona fuera de este ordenador y de tu red doméstica.",
    ["Paste API key"] = "Pegar clave API",
    ["Paste endpoint URL"] = "Pegar URL",
    ["Paste model ID"] = "Pegar ID de modelo",
    ["Sends one tiny message to your endpoint with the saved model ID and key, and shows how it answered. It uses next to nothing of your credits."] = "Envía un mensaje muy corto a tu endpoint con el ID de modelo y la clave guardados, y muestra cómo respondió. Gasta casi nada de tus créditos.",
    ["Test"] = "Probar",
    ["Test connection"] = "Probar conexión",
    ["Testing the connection…"] = "Probando la conexión…",
    ["Testing…"] = "Probando…",
    ["That is too long."] = "Es demasiado largo.",
    ["That was not accepted."] = "No fue aceptado.",
    ["The account is out of credits. Add credits with your provider."] = "La cuenta no tiene créditos. Añade créditos en tu proveedor.",
    ["The address must start with https:// or http://."] = "La dirección debe empezar por https:// o http://.",
    ["The address sends you somewhere else. Use the final address from your provider."] = "La dirección te envía a otro sitio. Usa la dirección final que te dé tu proveedor.",
    ["The clipboard does not hold a model ID."] = "El portapapeles no tiene un ID de modelo.",
    ["The clipboard does not hold a web address."] = "El portapapeles no tiene una dirección web.",
    ["The clipboard does not hold an API key."] = "El portapapeles no tiene una clave de API.",
    ["The clipboard is empty. Copy it first."] = "El portapapeles está vacío. Cópialo primero.",
    ["The connection test failed."] = "La prueba de conexión falló.",
    ["The connection works. The endpoint accepted your model and key."] = "La conexión funciona. El endpoint aceptó tu modelo y tu clave.",
    ["The conversation service is not running, so nothing can be tested. Restart the game."] = "El servicio de conversación no está en marcha, así que no se puede probar nada. Reinicia el juego.",
    ["The custom provider did not accept your key. Check it in Settings > Conversation provider."] = "El proveedor personalizado rechazó tu clave. Revísala en Ajustes > Proveedor de conversación.",
    ["The custom provider did not answer. Check its address in Settings, or try again."] = "El proveedor personalizado no respondió. Revisa su dirección en Ajustes o reintenta.",
    ["The custom provider does not know that model ID. Check it in Settings."] = "El proveedor personalizado no conoce ese ID de modelo. Revísalo en Ajustes.",
    ["The custom provider is not set up, so Convai is used. Add its URL and model ID in Settings."] = "Sin proveedor personalizado, se usa Convai. Añade URL e ID de modelo en Ajustes.",
    ["The custom provider is rate limiting you. Try again in a moment."] = "El proveedor personalizado está limitando tus peticiones. Prueba en un momento.",
    ["The custom provider says your account is out of credits. Add credits there, then try again."] = "El proveedor personalizado dice que no quedan créditos. Recárgalos y reintenta.",
    ["The endpoint URL was removed."] = "URL del endpoint eliminada.",
    ["The endpoint answered with no text. Check the model ID."] = "El endpoint respondió sin texto. Revisa el ID de modelo.",
    ["The endpoint did not accept your API key."] = "El endpoint no aceptó tu clave API.",
    ["The endpoint did not answer. Check its address."] = "El endpoint no respondió. Revisa su dirección.",
    ["The endpoint does not know that model ID."] = "El endpoint no conoce ese ID de modelo.",
    ["The endpoint is rate limiting you. Try again in a moment."] = "El endpoint te limita las peticiones. Prueba en un momento.",
    ["The endpoint is rate limiting you. Wait about {seconds} seconds, then try again."] = "El endpoint te limita las peticiones. Espera unos {seconds} segundos y reintenta.",
    ["The endpoint refused the request. Check the model ID and the address."] = "El endpoint rechazó la petición. Revisa el ID de modelo y la dirección.",
    ["The endpoint reported an error on its side. Try again in a moment."] = "El endpoint informó de un error en su lado. Prueba en un momento.",
    ["The endpoint took too long to answer."] = "El endpoint tardó demasiado en responder.",
    ["The model ID was removed."] = "ID de modelo eliminado.",
    ["The provider said: {detail}"] = "El proveedor dijo: {detail}",
    ["This address is not encrypted, which is fine on your own computer or home network."] = "Esta dirección no está cifrada, pero en tu ordenador o red doméstica está bien.",
    ["Use the base URL only: no password, query or #."] = "Usa solo la URL base: sin contraseña, sin consulta ni #.",
    ["Waiting for the endpoint to answer…"] = "Esperando a que el endpoint responda…",
    ["Custom: free daily limit reached"] = "Personalizado: límite diario gratuito alcanzado",
    ["New address saved. Paste your API key again for it."] = "Nueva dirección guardada. Vuelve a pegar tu clave API.",
    ["The free daily limit for this model was reached. It resets at {time}."] = "Límite diario gratuito de este modelo alcanzado. Se restablece a las {time}.",
    ["The free daily limit for this model was reached. Try again after it resets."] = "Límite diario gratuito de este modelo alcanzado. Inténtalo de nuevo tras el reinicio.",
    ["This model spends its reply on thinking. Choose a non-reasoning model in Settings."] = "Este modelo gasta su respuesta pensando. Elige un modelo sin razonamiento en Ajustes.",
    ["All"] = "Todos",
    ["Also changed: {names}."] = "También cambiado: {names}.",
    ["Choose any character from the list below. They do not need to be in your current party."] = "Elige cualquier personaje de la lista de abajo. No hace falta que esté en tu grupo actual.",
    ["Defaults restored."] = "Valores predeterminados restaurados.",
    ["Drag the slider, or press left and right, to turn the page."] = "Arrastra el deslizador o pulsa las flechas izquierda y derecha para cambiar de página.",
    ["How loud the mod’s voices are, for companions, characters and V’s typed lines. 100 is the normal level.\n\nAbove 100 the voices get louder, with a limiter so they do not crackle. The game’s own dialogue and sounds do not change.\n\nThe next reply uses it."] = "Qué tan fuertes suenan las voces del mod, en compañeros, personajes y las frases que escribe V. 100 es el nivel normal.\n\nPor encima de 100 las voces suenan más fuertes, con un limitador para que no distorsionen. Los diálogos y sonidos del propio juego no cambian.\n\nLa siguiente respuesta lo usa.",
    ["Not available right now."] = "No disponible por ahora.",
    ["Open Settings to restore its defaults."] = "Abre Ajustes para restaurar sus valores predeterminados.",
    ["Page"] = "Página",
    ["Show only the models whose name starts with this letter."] = "Muestra solo los modelos cuyo nombre empieza por esta letra.",
    ["Starts with"] = "Empieza por",
    ["Open AI NPC Cyberpunk Mod in the Mods list."] = "Abre AI NPC Cyberpunk Mod en la lista de mods.",
    ["The settings could not be saved. Nothing was changed."] = "No se pudieron guardar los ajustes. No se cambió nada.",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Mistral (with your free key, about 5,000 turns a day) or Local AI (unlimited)."] = "Hoy has usado tus {limit} turnos. Vuelven mañana. Para seguir hablando ahora, elige Mistral (con tu clave gratis, unos 5000 turnos al día) o Local AI (sin límite).",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Quién escribe las respuestas de tus compañeros. Un cambio espera a que no haya ninguna conversación en curso.\n\nEl nivel gratuito de Convai no necesita configuración y da mejores respuestas. La clave de API de Convai usa tu propia clave, y Mistral usa su plan gratuito con tu propia clave gratuita; la memoria se queda en este ordenador.\n\nCon Mistral, Local AI o Personalizado, la voz en la nube de Convai se sustituye por una voz local. El reconocimiento de voz se hace en este ordenador, así que la clave de voz funciona.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Quién escribe las respuestas de tus compañeros. Un cambio espera a que no haya ninguna conversación en curso.\n\nEl nivel gratuito de Convai no necesita configuración y da mejores respuestas. La clave de API de Convai usa tu propia clave, y Mistral usa su plan gratuito con tu propia clave gratuita; la memoria se queda en este ordenador.\n\nCon Mistral, Local AI o Personalizado, la voz en la nube de Convai se sustituye por una voz local. El reconocimiento de voz para la clave de voz aún no está disponible con ellos, así que escribe tus mensajes.",
    ["Privacy"] = "Privacidad",
    ["Send error reports automatically"] = "Enviar informes de error automáticamente",
    ["When something in the mod goes wrong, a short report goes to the developer so it can be fixed without asking you for logs. At most five a day.\n\nIt holds the error, the mod and requirement versions, your provider and voice choices, whether Mature content is on, your graphics card, the setup check and the log lines around the error. If replies stay slow, it also holds how long a few recent replies took, stage by stage.\n\nIt never holds keys, what you or the characters say, memories, audio or your Windows user name."] = "Cuando algo del mod sale mal, se envía un informe breve al desarrollador para que lo arregle sin pedirte registros. Como máximo, cinco al día. Si las respuestas siguen siendo lentas, también incluye cuánto tardaron algunas de las últimas respuestas, paso a paso.\n\nIncluye el error, las versiones del mod y de sus requisitos, tus opciones de proveedor y de voz, si el contenido para adultos está activado, tu tarjeta gráfica, la comprobación de la configuración y las líneas de registro alrededor del error.\n\nNunca incluye claves, lo que tú o los personajes dicen, recuerdos, audio ni tu nombre de usuario de Windows.",
    ["Error reports go to the developer automatically. Turn them off in Settings > Privacy."] = "Informes de error automáticos al desarrollador. Desactívalos en Ajustes > Privacidad.",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI"] = "El Gestor de compañeros necesita Mod Configuration Menu 0.10.5+ o Native Settings UI",
    ["Update Mod Configuration Menu to 0.10.5 or newer, or install Native Settings UI"] = "Actualiza Mod Configuration Menu a 0.10.5 o posterior, o instala Native Settings UI",
    ["Stand up to open the Companion Manager"] = "Ponte de pie para abrir el Gestor de compañeros",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI 1.96 or newer. Either one is enough. Install one from Nexus Mods, then restart the game."] = "El Gestor de compañeros necesita Mod Configuration Menu 0.10.5 o posterior, o Native Settings UI 1.96 o posterior. Cualquiera de los dos basta. Instala uno desde Nexus Mods y reinicia el juego.",
    ["Mod Configuration Menu is too old. Update it to 0.10.5 or newer, or install Native Settings UI, then restart the game."] = "Mod Configuration Menu es demasiado antiguo. Actualízalo a 0.10.5 o posterior, o instala Native Settings UI, y luego reinicia el juego.",
    ["Previous page"] = "Página anterior",
    ["Next page"] = "Página siguiente",
    ["Starts with: {letter}"] = "Empieza por: {letter}",
    ["Characters and party"] = "Personajes y grupo",
    ["Load a save first"] = "Carga una partida",
    ["Inviting characters and managing your party need a loaded game."] = "Invitar personajes y gestionar tu grupo requiere una partida cargada.",
    ["Voxtral (recommended)"] = "Voxtral (recomendado)",
    ["Defaults"] = "Estándar",
    ["Press Confirm to put every setting back to its default."] = "Pulsa Confirmar para devolver cada ajuste a su valor predeterminado.",
    ["Local AI stopped working and was restarted."] = "Local AI dejó de funcionar y se reinició.",
    ["Local AI runs mostly on your processor here, so replies will be slow."] = "Local AI se ejecuta sobre todo en tu procesador aquí, así que las respuestas serán lentas.",
    ["TweakXL is missing. Install TweakXL from Nexus Mods (nexusmods.com/cyberpunk2077/mods/4197), extract it into the Cyberpunk 2077 folder, then restart the game."] = "Falta TweakXL. Instala TweakXL desde Nexus Mods (nexusmods.com/cyberpunk2077/mods/4197), extráelo en la carpeta de Cyberpunk 2077 y reinicia el juego.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate. The microphone uses this language as a hint for non-English speech."] = "Solo cambia los menús y los avisos de este mod.\n\nLas voces de los personajes y el idioma en que hablas son cosas distintas. El micrófono usa este idioma como pista para el habla en otros idiomas.",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. Each character decides when; it stays rare.\n\nOmniVoice can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice while Convai answers: choosing it turns this off, and turning this on switches the voice to Pocket. With Mistral, Local AI or Custom it works."] = "Los compañeros hacen pausas, dudan, ríen o suspiran de vez en cuando, según su personalidad. Cada personaje decide cuándo; es poco frecuente.\n\nOmniVoice puede dar risas y suspiros; las demás voces solo añaden pausas.\n\nNo está disponible con la voz en la nube de Convai mientras responde Convai: elegirla desactiva esto, y activarlo cambia la voz a Pocket. Con Mistral, Local AI o Personalizado funciona.",
    ["Voxtral stops speaking; companion replies show as text until a key is saved."] = "Voxtral deja de hablar; las respuestas de los compañeros se muestran como texto hasta que se guarde una clave.",
    ["Conversations go back to Convai free tier."] = "Las conversaciones vuelven a Convai (plan gratuito).",
    ["Deletes the saved key."] = "Borra la clave guardada.",
    ["Nothing you use now depends on it."] = "Nada de lo que usas ahora depende de ello.",
    ["The Convai cloud voice cannot use Natural speech, so it was turned off."] = "La voz en la nube de Convai no puede usar el habla natural, así que se desactivó.",
    ["Custom endpoint"] = "Endpoint personalizado",
    ["Johnny Silverhand answers when you use the talk keys with nobody in front of you, as the voice in V’s head. He knows your jobs and your story so far, and what he thinks of you follows it.\n\nOnly while the story has him in V’s head. He stays quiet during scenes, calls, dialogue choices and fights, and when the game gives him a line.\n\nOn: he answers when you talk to him. Speaks up rarely: he also says something on his own, at most twice an hour. Speaks up often: at most six times an hour, never closer than five minutes. He speaks up after you meet someone he knows of, finish a job, a romance moves on, you arrive somewhere he knows, the Relic acts up, or a big fight ends.\n\nOn the Convai free tier each remark uses one of the day’s turns; remarks never take more than a tenth of them."] = "Johnny Silverhand te responde cuando usas las teclas de hablar con nadie delante, como la voz en la cabeza de V. Conoce tus trabajos y tu historia hasta ahora, y lo que piensa de ti va en esa misma línea.\n\nSolo mientras la historia lo tiene en la cabeza de V. Calla durante escenas, llamadas, opciones de diálogo y peleas, y cuando el juego le da una línea.\n\nActivado: responde cuando le hablas. Habla pocas veces: también dice algo por iniciativa propia, como máximo dos veces por hora. Habla a menudo: como máximo seis veces por hora, nunca con menos de cinco minutos de diferencia. Habla cuando conoces a alguien del que ha oído hablar, terminas un encargo, avanza un romance, llegas a un lugar que conoce, la Relic se descontrola o acaba una gran pelea.\n\nEn el nivel gratuito de Convai, cada comentario usa uno de los turnos del día; los comentarios nunca ocupan más de una décima parte de ellos.",
    ["Speaks up often"] = "Habla a menudo",
    ["Speaks up rarely"] = "Habla pocas veces",
    ["The address, API key and model ID of your OpenAI-compatible provider, and a connection test. Used when Custom is the Conversation provider."] = "La dirección, la clave API y el ID del modelo de tu proveedor compatible con OpenAI, y una prueba de conexión. Se usa cuando Personalizado es el proveedor de conversación.",
    ["V’s voice switches from Voxtral to Pocket."] = "La voz de V pasa de Voxtral a Pocket.",
    ["OmniVoice · needs Omni pack"] = "OmniVoice · sin paquete Omni",
    ["OmniVoice · needs Omni voice"] = "OmniVoice · falta voz Omni",
    ["OmniVoice · short wait"] = "OmniVoice · espera breve",
    ["Requires the Companion voices to be an OmniVoice choice"] = "Requiere que las voces de los compañeros sean la opción OmniVoice",
    ["V’s voice switches from OmniVoice to Pocket."] = "La voz de V pasa de OmniVoice a Pocket.",
    ["When you type a line, V says it out loud too, in the male or female V voice that matches yours. Push-to-talk is never replayed.\n\nV speaks first, then the companion answers. V’s line is always waited for, and is given up only if it is stuck with no audio after about 30 s. The line always shows as a subtitle.\n\nPocket: runs on your processor and starts in about 0.2 s. If the companions use another voice, it loads its own small voice model just for V.\n\nVoxtral: made in the cloud with your Mistral key, so nothing loads on your PC. Starts in about a second, in English and many other languages.\n\nOmniVoice: uses the same GPU voice as your companions (only while they use OmniVoice); no extra model loads. It adds a short wait before replies to typed lines (about a second more than Pocket, before V starts), because V speaks first and the companion answers after."] = "Cuando escribes una línea, V también la dice en voz alta, con la voz masculina o femenina de V que coincida con la tuya. Lo dicho con pulsar para hablar nunca se repite.\n\nV habla primero y luego responde el compañero. A la línea de V siempre se la espera, y solo se abandona si se atasca y lleva unos 30 s sin audio. La línea siempre aparece como subtítulo.\n\nPocket: se ejecuta en tu procesador y empieza en unos 0,2 s. Si los compañeros usan otra voz, carga su propio modelo de voz pequeño solo para V.\n\nVoxtral: se genera en la nube con tu clave de Mistral, así que nada se carga en tu PC. Empieza en un segundo aproximadamente, en inglés y en muchos otros idiomas.\n\nOmniVoice: usa la misma voz GPU que tus compañeros (solo mientras ellos usen OmniVoice); no se carga ningún modelo adicional. Añade una breve espera antes de las respuestas a líneas escritas (aproximadamente un segundo más que Pocket, antes de que empiece V), porque V habla primero y el compañero responde después.",
    ["V’s voice"] = "Voz de V",
    ["V (male voice)"] = "V (voz masculina)",
    ["V (female voice)"] = "V (voz femenina)",
    ["Used for V’s typed lines: Pocket, OmniVoice and the Voxtral cloud voice copy it."] = "Se usa para las líneas escritas de V: Pocket, OmniVoice y la voz en la nube de Voxtral la copian.",
    ["V speaks with the voice of your installed V voice mod, or the shipped V voice."] = "V habla con la voz de tu mod de voz de V instalado, o con la voz original de V.",
    ["Remove the voice clip? V goes back to the voice of your installed V voice mod, or the shipped V voice."] = "¿Quitar el clip de voz? V vuelve a la voz de tu mod de voz de V instalado o a la voz original.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Replies show as text. Choose Pocket in Settings to hear voices."] = "OmniVoice necesita una tarjeta gráfica NVIDIA y este PC no tiene ninguna que funcione. Las respuestas se muestran como texto. Elige Pocket en Ajustes para oír las voces.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Companions are using {voice} instead."] = "OmniVoice necesita una tarjeta gráfica NVIDIA y este PC no tiene ninguna que funcione. Los compañeros usan {voice} en su lugar.",
    ["OmniVoice needs NVIDIA"] = "OmniVoice necesita NVIDIA",
    ["This PC has no NVIDIA graphics card, which OmniVoice needs. OmniVoice will not start here. Choose Pocket to hear voices."] = "Este PC no tiene una tarjeta gráfica NVIDIA, que OmniVoice necesita. OmniVoice no se iniciará aquí. Elige Pocket para oír las voces.",
    ["{voice} · needs NVIDIA card"] = "{voice} · requiere tarjeta NVIDIA",
    ["The Pocket voice for {language} is installed, but it needs the {language} voice language pack, which is missing. Replies in {language} show as text until you install it."] = "La voz Pocket en {language} está instalada, pero falta el paquete de voz del idioma {language}. Las respuestas en {language} se muestran como texto hasta que lo instales.",
    ["French"] = "francés",
    ["Italian"] = "italiano",
    ["German"] = "alemán",
    ["Spanish"] = "español",
    ["Portuguese"] = "portugués",

    ["OmniVoice needs more graphics memory than is free next to the game. Pocket is used."] = "OmniVoice necesita más memoria gráfica de la que queda libre junto al juego. Se usa Pocket.",
    ["OmniVoice needs 12 GB"] = "OmniVoice necesita 12 GB",
    ["{voice} · needs 12 GB card"] = "{voice} · requiere tarjeta de 12 GB",
    ["The graphics card in this PC has less than the 12 GB OmniVoice needs next to the game. If it cannot start, Pocket is used. Choose Pocket to skip the wait."] = "La tarjeta gráfica de este PC tiene menos de los 12 GB que OmniVoice necesita junto al juego. Si no puede iniciarse, se usa Pocket. Elige Pocket para saltarte la espera.",
    ["The Runtime is out of date. Apply its update zips one by one, or get the full Runtime."] = "El Runtime está desactualizado. Aplica sus zips uno a uno o descarga el Runtime completo.",
    ["The Scripts and Runtime do not match. Update whichever is older. See Help in Settings."] = "Los Scripts y el Runtime no coinciden. Actualiza el más antiguo. Consulta Ayuda en Ajustes.",
    ["Scripts {scripts} and Runtime {runtime} do not match: the Runtime is out of date. Apply the Runtime update zips from the updates folder on the mod’s Hugging Face page one by one, starting from your version, or download the full Runtime. Extract each into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} y Runtime {runtime} no coinciden: el Runtime está desactualizado. Aplica uno a uno los zips de actualización del Runtime de la carpeta updates de la página de Hugging Face del mod, empezando por tu versión, o descarga el Runtime completo. Extrae cada uno en la carpeta de Cyberpunk 2077 y reinicia el juego.",
    ["Scripts {scripts} and Runtime {runtime} do not match. Update whichever is older: the Scripts from Nexus Mods, or the Runtime from the mod’s Hugging Face page (its update zips one by one, or the full Runtime). Extract into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} y Runtime {runtime} no coinciden. Actualiza el más antiguo: los Scripts desde Nexus Mods, o el Runtime desde la página de Hugging Face del mod (sus zips de actualización uno a uno, o el Runtime completo). Extrae en la carpeta de Cyberpunk 2077 y reinicia el juego.",
    ["The conversation service did not answer the setup check, so its Runtime is probably older than these Scripts. Download the full Runtime from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, then restart the game."] = "El servicio de conversación no respondió a la comprobación de instalación, así que su Runtime probablemente es anterior a estos Scripts. Descarga el Runtime completo desde la página de Hugging Face del mod y extráelo en la carpeta de Cyberpunk 2077, luego reinicia el juego.",
}
